18	template<typename T>
19	class ScatterKernel {
20	public:
21	    __aicore__ inline ScatterKernel() {}
22	
23	    __aicore__ inline void Init(GM_ADDR self, GM_ADDR index, GM_ADDR src,
24	                                 int64_t outerSize, int64_t innerSize,
25	                                 int64_t indexSize, int64_t reduceMode);
26	    __aicore__ inline void Process();
27	
28	private:
29	    __aicore__ inline void ProcessRow(int64_t outerIdx);
30	
31	    TPipe pipe;
32	
33	    // Buffers: selfBuf (整行) + indexBuf + srcBuf
34	    TBuf<TPosition::VECIN> selfBuf;
35	    TBuf<TPosition::VECIN> indexBuf;
36	    TBuf<TPosition::VECIN> srcBuf;
37	
38	    GlobalTensor<T> selfGm;
39	    GlobalTensor<int32_t> indexGm;
40	    GlobalTensor<T> srcGm;
41	
42	    int64_t outerSize_ = 0;
43	    int64_t innerSize_ = 0;
44	    int64_t indexSize_ = 0;
45	    int64_t reduceMode_ = 0;
46	
47	    int64_t selfRowBytes_ = 0;
48	    int64_t indexRowBytes_ = 0;
49	    int64_t srcRowBytes_ = 0;
50	};
51	
52	template<typename T>
53	__aicore__ inline void ScatterKernel<T>::Init(GM_ADDR self, GM_ADDR index, GM_ADDR src,
54	                                                 int64_t outerSize, int64_t innerSize,
55	                                                 int64_t indexSize, int64_t reduceMode) {
56	    outerSize_ = outerSize;
57	    innerSize_ = innerSize;
58	    indexSize_ = indexSize;
59	    reduceMode_ = reduceMode;
60	
61	    selfGm.SetGlobalBuffer((__gm__ T*)self, outerSize * innerSize);
62	    indexGm.SetGlobalBuffer((__gm__ int32_t*)index, outerSize * indexSize);
63	    srcGm.SetGlobalBuffer((__gm__ T*)src, outerSize * indexSize);
64	
65	    // 32字节对齐的行字节数
66	    selfRowBytes_ = (innerSize * sizeof(T) + 31) / 32 * 32;
67	    indexRowBytes_ = (indexSize * sizeof(int32_t) + 31) / 32 * 32;
68	    srcRowBytes_ = (indexSize * sizeof(T) + 31) / 32 * 32;
69	
70	    // 初始化 UB buffer
71	    pipe.InitBuffer(selfBuf, selfRowBytes_);
72	    pipe.InitBuffer(indexBuf, indexRowBytes_);
73	    pipe.InitBuffer(srcBuf, srcRowBytes_);
74	}
75	
76	template<typename T>
77	__aicore__ inline void ScatterKernel<T>::ProcessRow(int64_t outerIdx) {
78	    // 1. 读入 self 整行到 UB
79	    LocalTensor<T> selfLocal = selfBuf.Get<T>();
80	    {
81	        DataCopyExtParams copyParams;
82	        copyParams.blockCount = 1;
83	        copyParams.blockLen = static_cast<uint32_t>(innerSize_ * sizeof(T));
84	        copyParams.srcStride = 0;
85	        copyParams.dstStride = 0;
86	        DataCopyPadExtParams<T> padParams;
87	        padParams.isPad = false;
88	        DataCopyPad(selfLocal, selfGm[outerIdx * innerSize_], copyParams, padParams);
89	    }
90	    PipeBarrier<PIPE_ALL>();
91	
92	    // 2. 加载 index 行到 UB
93	    LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
94	    {
95	        DataCopyExtParams copyParams;
96	        copyParams.blockCount = 1;
97	        copyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
98	        copyParams.srcStride = 0;
99	        copyParams.dstStride = 0;
100	        DataCopyPadExtParams<int32_t> padParams;
101	        padParams.isPad = false;
102	        DataCopyPad(indexLocal, indexGm[outerIdx * indexSize_], copyParams, padParams);
103	    }
104	    PipeBarrier<PIPE_ALL>();
105	
106	    // 3. 加载 src 行到 UB
107	    LocalTensor<T> srcLocal = srcBuf.Get<T>();
108	    {
109	        DataCopyExtParams copyParams;
110	        copyParams.blockCount = 1;
111	        copyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
112	        copyParams.srcStride = 0;
113	        copyParams.dstStride = 0;
114	        DataCopyPadExtParams<T> padParams;
115	        padParams.isPad = false;
116	        DataCopyPad(srcLocal, srcGm[outerIdx * indexSize_], copyParams, padParams);
117	    }
118	    PipeBarrier<PIPE_ALL>();
119	
120	    // 4. Scatter 写入: 按 index 将 src 值写入 selfLocal
121	    for (int64_t k = 0; k < indexSize_; ++k) {
122	        int32_t idx = indexLocal.GetValue(k);
123	        // 边界检查
124	        if (idx < 0 || idx >= innerSize_) {
125	            continue;
126	        }
127	        T val = srcLocal.GetValue(k);
128	        if (reduceMode_ == 0) {
129	            // replace mode
130	            selfLocal.SetValue(idx, val);
131	        } else if (reduceMode_ == 1) {
132	            // add mode
133	            T current = selfLocal.GetValue(idx);
134	            selfLocal.SetValue(idx, current + val);
135	        } else if (reduceMode_ == 2) {
136	            // multiply mode
137	            T current = selfLocal.GetValue(idx);
138	            selfLocal.SetValue(idx, current * val);
139	        }
140	    }
141	    PipeBarrier<PIPE_ALL>();
142	
143	    // 5. 写回 self 行到 GM
144	    {
145	        DataCopyExtParams copyParams;
146	        copyParams.blockCount = 1;
147	        copyParams.blockLen = static_cast<uint32_t>(innerSize_ * sizeof(T));
148	        copyParams.srcStride = 0;
149	        copyParams.dstStride = 0;
150	        DataCopyPad(selfGm[outerIdx * innerSize_], selfLocal, copyParams);
151	    }
152	    PipeBarrier<PIPE_ALL>();
153	}
154	
155	template<typename T>
156	__aicore__ inline void ScatterKernel<T>::Process() {
157	    int64_t blockIdx_ = GetBlockIdx();
158	    int64_t blockDim = (outerSize_ < MAX_CORES) ? outerSize_ : MAX_CORES;
159	
160	    if (blockIdx_ >= blockDim) {
161	        return;
162	    }
163	
164	    // 每核分配的行数
165	    int64_t base = outerSize_ / blockDim;
166	    int64_t remainder = outerSize_ % blockDim;
167	    int64_t myStart, myRows;
168	    if (blockIdx_ < remainder) {
169	        myStart = blockIdx_ * (base + 1);
170	        myRows = base + 1;
171	    } else {
172	        myStart = remainder * (base + 1) + (blockIdx_ - remainder) * base;
173	        myRows = base;
174	    }
175	
176	    for (int64_t r = 0; r < myRows; ++r) {
177	        int64_t outerIdx = myStart + r;
178	        if (outerIdx >= outerSize_) break;
179	        ProcessRow(outerIdx);
180	    }
181	}
