185	                                                int64_t outerSize, int64_t innerSize,
186	                                                int64_t indexSize, int64_t reduceMode,
187	                                                int64_t dtypeSize) {
188	    if (dtypeSize == 4) {
189	        ScatterKernel<float> op;
190	        op.Init(self, index, src, outerSize, innerSize, indexSize, reduceMode);
191	        op.Process();
192	    } else if (dtypeSize == 2) {
193	        ScatterKernel<half> op;
194	        op.Init(self, index, src, outerSize, innerSize, indexSize, reduceMode);
195	        op.Process();
196	    }
