33	inline int32_t CeilDivI32(int32_t a, int32_t b)
34	{
35	    if (b == 0) { return 0; }
36	    return (a + b - 1) / b;
37	}
38	
39	int32_t ChooseBlockM(int32_t totalM)
40	{
41	    for (int32_t candidate : {64, 32, 16, 8, 4, 2}) {
42	        if (totalM >= candidate) {
43	            return candidate;
44	        }
45	    }
46	    return 2;
47	}
48	
49	void CheckInputTensor(const at::Tensor &tensor, const char *name, const at::Tensor &reference)
50	{
51	    TORCH_CHECK(tensor.dim() == 2, name, " must be a 2D tensor");
52	    TORCH_CHECK(tensor.scalar_type() == at::kFloat, name, " must be float32");
53	    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
54	    TORCH_CHECK(tensor.device().type() == reference.device().type(), name, " must be on the same device as x0");
55	    TORCH_CHECK(tensor.sizes()[1] == reference.sizes()[1], name, " must have the same trailing width as x0");
56	}
57	
58	struct ConcatDim0LaunchData {
59	    at::Tensor y;
60	    at::Tensor tilingNpu;
61	    int32_t usedCoreNum;
62	};
63	
64	ConcatDim0LaunchData PrepareConcatDim0(const std::array<const at::Tensor *, 4> &inputs, int32_t inputCount)
65	{
66	    TORCH_CHECK(inputCount >= 1 && inputCount <= 4, "inputCount must be in [1, 4]");
67	
68	    const at::Tensor &x0 = *inputs[0];
69	    CheckInputTensor(x0, "x0", x0);
70	    TORCH_CHECK(x0.device().type() == at::kPrivateUse1, "x0 must be on NPU/PrivateUse1 device");
71	
72	    int32_t m[4] = {
73	        static_cast<int32_t>(x0.sizes()[0]),
74	        0,
75	        0,
76	        0,
77	    };
78	    for (int32_t index = 1; index < inputCount; ++index) {
79	        const at::Tensor &tensor = *inputs[index];
80	        const std::string name = "x" + std::to_string(index);
81	        CheckInputTensor(tensor, name.c_str(), x0);
82	        m[index] = static_cast<int32_t>(tensor.sizes()[0]);
83	    }
84	
85	    const int32_t n = static_cast<int32_t>(x0.sizes()[1]);
86	    const int32_t totalM = m[0] + m[1] + m[2] + m[3];
87	    at::Tensor y = at::empty({static_cast<int64_t>(totalM), static_cast<int64_t>(n)}, x0.options());
88	    if (totalM == 0 || n == 0) {
89	        return {y, at::Tensor(), 0};
90	    }
91	
92	    const int32_t blockM = ChooseBlockM(totalM);
93	    const int32_t subBlockM = blockM / DEFAULT_VEC_NUM;
94	    const int32_t blockNum = CeilDivI32(totalM, blockM);
95	    const int32_t usedCoreNum = std::min(DEFAULT_NUM_PHYSICAL_CORES, blockNum);
96	    const int32_t tasksPerCore = CeilDivI32(blockNum, usedCoreNum);
97	
98	    at::Tensor tilingCpu = at::empty(
99	        {static_cast<long>(sizeof(ConcatDim0Tiling))},
100	        at::device(at::kCPU).dtype(at::kByte));
101	    auto *tiling = reinterpret_cast<ConcatDim0Tiling *>(tilingCpu.data_ptr());
102	    tiling->M0 = m[0];
103	    tiling->M1 = m[1];
104	    tiling->M2 = m[2];
105	    tiling->M3 = m[3];
106	    tiling->inputCount = inputCount;
107	    tiling->N = n;
108	    tiling->totalM = totalM;
109	    tiling->blockM = blockM;
110	    tiling->subBlockM = subBlockM;
111	    tiling->blockNum = blockNum;
112	    tiling->usedCoreNum = usedCoreNum;
113	    tiling->tasksPerCore = tasksPerCore;
114	
115	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
116	    return {y, tilingNpu, usedCoreNum};
117	}
