119	at::Tensor concat_dim0_1(const at::Tensor &x0)
120	{
121	    auto data = PrepareConcatDim0({&x0, nullptr, nullptr, nullptr}, 1);
122	    if (data.y.numel() == 0) {
123	        return data.y;
124	    }
125	    uint32_t blockDim = static_cast<uint32_t>(data.usedCoreNum);
126	    EXEC_KERNEL_CMD(concat_dim0_1, blockDim,
127	                    x0, nullptr, nullptr, nullptr, data.y, data.tilingNpu);
128	    return data.y;
129	}
