18	constexpr int64_t MAX_CORES = 40;
19	
20	at::Tensor scatter(const at::Tensor& self, int64_t dim, const at::Tensor& index,
21	                   const at::Tensor& src, int64_t reduceMode) {
22	    // ---- 输入校验 ----
23	    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
24	                "scatter: self must be on NPU device");
25	    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
26	                "scatter: index must be on NPU device");
27	    TORCH_CHECK(src.device().type() == at::DeviceType::PrivateUse1,
28	                "scatter: src must be on NPU device");
29	
30	    int64_t ndim = self.dim();
31	    if (dim < 0) dim += ndim;
32	
33	    TORCH_CHECK(dim >= 0 && dim < ndim,
34	                "scatter: dim out of range, got dim=", dim);
35	    TORCH_CHECK(index.dim() == ndim,
36	                "scatter: index must have same ndim as self");
37	    TORCH_CHECK(src.dim() == ndim,
38	                "scatter: src must have same ndim as self");
39	    TORCH_CHECK(index.sizes() == src.sizes(),
40	                "scatter: index and src must have the same shape");
41	
42	    TORCH_CHECK(self.scalar_type() == at::kFloat ||
43	                self.scalar_type() == at::kHalf ||
44	                self.scalar_type() == at::kBFloat16,
45	                "scatter: only float32, float16 and bfloat16 are supported");
46	
47	    // ---- 连续化 ----
48	    at::Tensor selfContiguous = self.contiguous();
49	    at::Tensor indexContiguous = index.contiguous();
50	    at::Tensor srcContiguous = src.contiguous();
51	
52	    // ---- 维度参数 ----
53	    int64_t N = selfContiguous.size(dim);   // self 在 dim 维度的大小
54	    int64_t K = indexContiguous.size(dim);  // index/src 在 dim 维度的大小
55	    int64_t dtypeSize = selfContiguous.element_size();
56	
57	    // ---- Index 转 int32 ----
58	    auto indexInt32 = indexContiguous.to(at::kInt);
59	
60	    // ---- 3D 维度统一化 ----
61	    // transpose(dim, -1) 将 dim 移到最后一维，再 reshape 为 [batch, rows, N/K]
62	    int64_t batch = 1;
63	    for (int64_t i = 0; i < dim; i++) batch *= selfContiguous.size(i);
64	    int64_t rows = selfContiguous.numel() / (batch * N);
65	    int64_t outerSize = batch * rows;
66	
67	    auto selfFlat = selfContiguous.transpose(dim, -1).contiguous().reshape({outerSize, N});
68	    auto indexFlat = indexInt32.transpose(dim, -1).contiguous().reshape({outerSize, K});
69	    auto srcFlat = srcContiguous.transpose(dim, -1).contiguous().reshape({outerSize, K});
70	
71	    // ---- 输出: scatter 是 in-place 操作，结果写回 self ----
72	    // 创建输出 tensor (clone of self)
73	    auto output = selfContiguous.clone();
74	    auto outputFlat = output.transpose(dim, -1).contiguous().reshape({outerSize, N});
75	
76	    // ---- 分批 launch (模式 B: 每核一行) ----
77	    int64_t processed = 0;
78	    while (processed < outerSize) {
79	        int64_t batchLaunch = outerSize - processed;
80	        if (batchLaunch > MAX_CORES) batchLaunch = MAX_CORES;
81	        uint32_t blockDim = static_cast<uint32_t>(batchLaunch);
82	        if (blockDim < 1) blockDim = 1;
83	
84	        auto selfBatch = outputFlat.narrow(0, processed, batchLaunch);
85	        auto indexBatch = indexFlat.narrow(0, processed, batchLaunch);
86	        auto srcBatch = srcFlat.narrow(0, processed, batchLaunch);
87	
88	        int64_t batchOuterSize = batchLaunch;
89	        int64_t batchInnerSize = N;
90	        int64_t batchIndexSize = K;
91	        int64_t batchDtypeSize = dtypeSize;
92	
93	        EXEC_KERNEL_CMD(scatter, blockDim, selfBatch, indexBatch, srcBatch,
94	                        batchOuterSize, batchInnerSize, batchIndexSize,
95	                        reduceMode, batchDtypeSize);
96	        processed += batchLaunch;
97	    }
98	
99	    // ---- 输出 reshape 还原 ----
100	    return output;
101	}
102	
103	}  // namespace ascend_kernel
