#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t UB_CAPACITY = 192 * 1024;
constexpr int64_t MAX_CORES = 40;

template<typename T>
class ScatterKernel {
public:
    __aicore__ inline ScatterKernel() {}

    __aicore__ inline void Init(GM_ADDR self, GM_ADDR index, GM_ADDR src,
                                 int64_t selfOuterSize, int64_t indexOuterSize,
                                 int64_t innerSize, int64_t indexSize,
                                 int64_t reduceMode);
    __aicore__ inline void Process();

private:
    __aicore__ inline void ProcessRow(int64_t outerIdx);

    TPipe pipe;

    // Buffers: selfBuf (整行) + indexBuf + srcBuf
    TBuf<TPosition::VECIN> selfBuf;
    TBuf<TPosition::VECIN> indexBuf;
    TBuf<TPosition::VECIN> srcBuf;

    GlobalTensor<T> selfGm;
    GlobalTensor<int32_t> indexGm;
    GlobalTensor<T> srcGm;

    int64_t selfOuterSize_ = 0;
    int64_t indexOuterSize_ = 0;
    int64_t innerSize_ = 0;
    int64_t indexSize_ = 0;
    int64_t reduceMode_ = 0;

    int64_t selfRowBytes_ = 0;
    int64_t indexRowBytes_ = 0;
    int64_t srcRowBytes_ = 0;
};

template<typename T>
__aicore__ inline void ScatterKernel<T>::Init(GM_ADDR self, GM_ADDR index, GM_ADDR src,
                                               int64_t selfOuterSize, int64_t indexOuterSize,
                                               int64_t innerSize, int64_t indexSize,
                                               int64_t reduceMode) {
    selfOuterSize_ = selfOuterSize;
    indexOuterSize_ = indexOuterSize;
    innerSize_ = innerSize;
    indexSize_ = indexSize;
    reduceMode_ = reduceMode;

    selfGm.SetGlobalBuffer((__gm__ T*)self, selfOuterSize * innerSize);
    indexGm.SetGlobalBuffer((__gm__ int32_t*)index, indexOuterSize * indexSize);
    srcGm.SetGlobalBuffer((__gm__ T*)src, indexOuterSize * indexSize);

    // 32字节对齐的行字节数
    selfRowBytes_ = (innerSize * sizeof(T) + 31) / 32 * 32;
    indexRowBytes_ = (indexSize * sizeof(int32_t) + 31) / 32 * 32;
    srcRowBytes_ = (indexSize * sizeof(T) + 31) / 32 * 32;

    // 初始化 UB buffer
    pipe.InitBuffer(selfBuf, selfRowBytes_);
    pipe.InitBuffer(indexBuf, indexRowBytes_);
    pipe.InitBuffer(srcBuf, srcRowBytes_);
}

template<typename T>
__aicore__ inline void ScatterKernel<T>::ProcessRow(int64_t outerIdx) {
    // 1. 读入 self 整行到 UB
    LocalTensor<T> selfLocal = selfBuf.Get<T>();
    {
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(innerSize_ * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;
        DataCopyPad(selfLocal, selfGm[outerIdx * innerSize_], copyParams, padParams);
    }
    PipeBarrier<PIPE_ALL>();

    // 2. 加载 index 行到 UB
    LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
    {
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPadExtParams<int32_t> padParams;
        padParams.isPad = false;
        DataCopyPad(indexLocal, indexGm[outerIdx * indexSize_], copyParams, padParams);
    }
    PipeBarrier<PIPE_ALL>();

    // 3. 加载 src 行到 UB
    LocalTensor<T> srcLocal = srcBuf.Get<T>();
    {
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;
        DataCopyPad(srcLocal, srcGm[outerIdx * indexSize_], copyParams, padParams);
    }
    PipeBarrier<PIPE_ALL>();

    // 4. Scatter 写入: 按 index 将 src 值写入 selfLocal
    for (int64_t k = 0; k < indexSize_; ++k) {
        int32_t idx = indexLocal.GetValue(k);
        // 边界检查
        if (idx < 0 || idx >= innerSize_) {
            continue;
        }
        T val = srcLocal.GetValue(k);
        if (reduceMode_ == 0) {
            // replace mode
            selfLocal.SetValue(idx, val);
        } else if (reduceMode_ == 1) {
            // add mode - use FP32 for computation to avoid half precision issues
            if constexpr (sizeof(T) == sizeof(half)) {
                float current_f = static_cast<float>(selfLocal.GetValue(idx));
                float val_f = static_cast<float>(val);
                float result_f = current_f + val_f;
                selfLocal.SetValue(idx, static_cast<T>(result_f));
            } else {
                T current = selfLocal.GetValue(idx);
                selfLocal.SetValue(idx, current + val);
            }
        } else if (reduceMode_ == 2) {
            // multiply mode - use FP32 for computation
            if constexpr (sizeof(T) == sizeof(half)) {
                float current_f = static_cast<float>(selfLocal.GetValue(idx));
                float val_f = static_cast<float>(val);
                float result_f = current_f * val_f;
                selfLocal.SetValue(idx, static_cast<T>(result_f));
            } else {
                T current = selfLocal.GetValue(idx);
                selfLocal.SetValue(idx, current * val);
            }
        }
    }
    PipeBarrier<PIPE_ALL>();

    // 5. 写回 self 行到 GM
    {
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(innerSize_ * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPad(selfGm[outerIdx * innerSize_], selfLocal, copyParams);
    }
    PipeBarrier<PIPE_ALL>();
}

template<typename T>
__aicore__ inline void ScatterKernel<T>::Process() {
    int64_t blockIdx_ = GetBlockIdx();
    int64_t blockDim = (indexOuterSize_ < MAX_CORES) ? indexOuterSize_ : MAX_CORES;

    if (blockIdx_ >= blockDim) {
        return;
    }

    // 每核分配的行数
    int64_t base = indexOuterSize_ / blockDim;
    int64_t remainder = indexOuterSize_ % blockDim;
    int64_t myStart, myRows;
    if (blockIdx_ < remainder) {
        myStart = blockIdx_ * (base + 1);
        myRows = base + 1;
    } else {
        myStart = remainder * (base + 1) + (blockIdx_ - remainder) * base;
        myRows = base;
    }

    for (int64_t r = 0; r < myRows; ++r) {
        int64_t outerIdx = myStart + r;
        if (outerIdx >= indexOuterSize_) break;
        ProcessRow(outerIdx);
    }
}

// Kernel 入口
extern "C" __global__ __aicore__ void scatter(GM_ADDR self, GM_ADDR index, GM_ADDR src,
                                                int64_t selfOuterSize, int64_t indexOuterSize,
                                                int64_t innerSize, int64_t indexSize,
                                                int64_t reduceMode, int64_t dtypeSize) {
    if (dtypeSize == 4) {
        ScatterKernel<float> op;
        op.Init(self, index, src, selfOuterSize, indexOuterSize, innerSize, indexSize, reduceMode);
        op.Process();
    } else if (dtypeSize == 2) {
        ScatterKernel<half> op;
        op.Init(self, index, src, selfOuterSize, indexOuterSize, innerSize, indexSize, reduceMode);
        op.Process();
    }
}
