#include "torch_kernel_helper.h"
#include "kernels/aclrtlaunch_scatter.h"
#include <torch/extension.h>
#include <torch/library.h>

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;

at::Tensor scatter(const at::Tensor& self, int64_t dim, const at::Tensor& index,
                   const at::Tensor& src, int64_t reduceMode) {
    // ---- 输入校验 ----
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "scatter: self must be on NPU device");
    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
                "scatter: index must be on NPU device");
    TORCH_CHECK(src.device().type() == at::DeviceType::PrivateUse1,
                "scatter: src must be on NPU device");

    int64_t ndim = self.dim();
    if (dim < 0) dim += ndim;

    TORCH_CHECK(dim >= 0 && dim < ndim,
                "scatter: dim out of range, got dim=", dim);
    TORCH_CHECK(index.dim() == ndim,
                "scatter: index must have same ndim as self");
    TORCH_CHECK(src.dim() == ndim,
                "scatter: src must have same ndim as self");
    TORCH_CHECK(index.sizes() == src.sizes(),
                "scatter: index and src must have the same shape");

    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf ||
                self.scalar_type() == at::kBFloat16,
                "scatter: only float32, float16 and bfloat16 are supported");

    // ---- 连续化 ----
    at::Tensor selfContiguous = self.contiguous();
    at::Tensor indexContiguous = index.contiguous();
    at::Tensor srcContiguous = src.contiguous();

    // ---- 维度参数 ----
    int64_t N = selfContiguous.size(dim);   // self 在 dim 维度的大小
    int64_t K = indexContiguous.size(dim);  // index/src 在 dim 维度的大小

    // ---- Index 转 int32 ----
    auto indexInt32 = indexContiguous.to(at::kInt);

    // ---- 3D 维度统一化 ----
    // 分别为 self、index/src 计算 outerSize
    int64_t selfBatch = 1, indexBatch = 1;
    for (int64_t i = 0; i < dim; i++) {
        selfBatch *= selfContiguous.size(i);
        indexBatch *= indexContiguous.size(i);
    }
    int64_t selfRows = selfContiguous.numel() / (selfBatch * N);
    int64_t indexRows = indexContiguous.numel() / (indexBatch * K);
    int64_t selfOuterSize = selfBatch * selfRows;
    int64_t indexOuterSize = indexBatch * indexRows;

    auto selfFlat = selfContiguous.transpose(dim, -1).contiguous().reshape({selfOuterSize, N});
    auto indexFlat = indexInt32.transpose(dim, -1).contiguous().reshape({indexOuterSize, K});
    auto srcFlat = srcContiguous.transpose(dim, -1).contiguous().reshape({indexOuterSize, K});

    // ---- 对于 FP16/BF16，升精度到 FP32 计算，保证精度 ----
    bool isFp32 = (selfContiguous.scalar_type() == at::kFloat);
    at::Tensor selfFp32, srcFp32, outputFp32;

    if (!isFp32) {
        selfFp32 = selfContiguous.to(at::kFloat);
        srcFp32 = srcContiguous.to(at::kFloat);
    } else {
        selfFp32 = selfContiguous;
        srcFp32 = srcContiguous;
    }

    auto selfFlatFp32 = selfFp32.transpose(dim, -1).contiguous().reshape({selfOuterSize, N});
    auto srcFlatFp32 = srcFp32.transpose(dim, -1).contiguous().reshape({indexOuterSize, K});

    // 输出也是 FP32
    outputFp32 = selfFp32.clone();
    auto outputTransposed = outputFp32.transpose(dim, -1).contiguous();
    auto outputFlat = outputTransposed.reshape({selfOuterSize, N});

    // ---- 分批 launch (模式 B: 每核一行) ----
    int64_t processed = 0;
    while (processed < indexOuterSize) {
        int64_t batchLaunch = indexOuterSize - processed;
        if (batchLaunch > MAX_CORES) batchLaunch = MAX_CORES;
        uint32_t blockDim = static_cast<uint32_t>(batchLaunch);
        if (blockDim < 1) blockDim = 1;

        auto selfBatch = outputFlat.narrow(0, processed, batchLaunch);
        auto indexBatch = indexFlat.narrow(0, processed, batchLaunch);
        auto srcBatch = srcFlatFp32.narrow(0, processed, batchLaunch);

        int64_t batchSelfOuterSize = selfOuterSize;  // self 的总行数
        int64_t batchIndexOuterSize = batchLaunch;   // 本次处理的 index 行数
        int64_t batchInnerSize = N;
        int64_t batchIndexSize = K;
        int64_t batchDtypeSize = 4;  // 总是用 FP32 kernel

        EXEC_KERNEL_CMD(scatter, blockDim, selfBatch, indexBatch, srcBatch,
                        batchSelfOuterSize, batchIndexOuterSize, batchInnerSize,
                        batchIndexSize, reduceMode, batchDtypeSize);
        processed += batchLaunch;
    }

    // 将修改后的数据复制回 outputFp32
    outputFp32.transpose(dim, -1).copy_(outputTransposed);

    // ---- 降精度回原始类型 ----
    at::Tensor output;
    if (!isFp32) {
        output = outputFp32.to(self.scalar_type());
    } else {
        output = outputFp32;
    }

    return output;
}

}  // namespace ascend_kernel
